import Foundation
import MediaLibServerProtocol

/// 持久化的逐用户网页播放队列。页面只接受服务端已经授权的队列 DTO；浏览器
/// 通过同源 JSON 端点修改顺序和播放设置，令牌仍只存在于受保护的 HTML meta 中。
enum ServerWebQueuePage {
    static func render(serverName: String, queue: ServerQueueResponse, csrfToken: String, showAdministration: Bool, categories: [ServerLibraryCategory] = []) -> String {
        let items = queue.items.enumerated().map { index, item in itemMarkup(item, index: index, current: index == queue.currentPosition) }.joined()
        let sidebar = ServerWebNavigation.render(active: .queue, showAdministration: showAdministration, note: .playback, categories: categories)
        let pageHeader = ServerWebPageHeader.render(icon: .queue, eyebrow: "播放队列", title: "播放队列", subtitle: "队列属于当前账号并在服务端保存；在其他浏览器登录后仍可继续播放。")
        let csrf = escape(csrfToken)
        let safeServerName = escape(serverName)
        let repeatMode = escape(queue.repeatMode)
        let shuffleEnabled = queue.shuffleEnabled ? "true" : "false"
        let shuffleLabel = queue.shuffleEnabled ? "关闭随机" : "开启随机"
        let repeatSelected = { (value: String) in queue.repeatMode == value ? " selected" : "" }
        let emptyState = queue.items.isEmpty ? "队列为空，请从资料库加入媒体。" : "已同步"
        let disabled = queue.items.isEmpty ? " disabled" : ""
        return """
        <!doctype html><html lang="zh-Hans"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="color-scheme" content="light"><meta name="medialib-csrf-token" content="\(csrf)"><title>播放队列 · \(safeServerName)</title><link rel="stylesheet" href="/assets/queue.css"><link rel="stylesheet" href="/assets/app-shell.css?v=68"><script src="/assets/app-shell.js?v=68" defer></script><script src="/assets/queue.js" defer></script></head><body data-page-route="/queue" data-playback-filter="inProgress" data-repeat-mode="\(repeatMode)" data-shuffle-enabled="\(shuffleEnabled)" data-current-position="\(queue.currentPosition)"><a class="skip" href="#main">跳到主要内容</a><div class="shell">\(sidebar)<main id="main" tabindex="-1">\(pageHeader)<section class="queue-toolbar" aria-label="队列设置"><div><strong id="queue-count">\(queue.items.count) 项</strong><span id="queue-status" role="status" aria-live="polite">\(emptyState)</span></div><div class="toolbar-actions"><label class="select-control">循环<select id="repeat-mode"><option value="sequential"\(repeatSelected("sequential"))>顺序播放</option><option value="repeatOne"\(repeatSelected("repeatOne"))>单曲循环</option><option value="repeatAll"\(repeatSelected("repeatAll"))>列表循环</option></select></label><button id="shuffle-toggle" class="secondary" type="button" aria-pressed="\(shuffleEnabled)">\(shuffleLabel)</button><button id="clear-queue" class="danger" type="button"\(disabled)>清空队列</button></div></section><ol id="queue-list" class="queue-list" aria-live="polite">\(items)</ol><p id="queue-empty" class="empty"\(queue.items.isEmpty ? "" : " hidden")>队列为空。回到<a href="/library">资料库</a>，在媒体卡片上选择“加入队列”。</p></main></div></body></html>
        """
    }

    private static func itemMarkup(_ item: ServerQueueItem, index: Int, current: Bool) -> String {
        guard let id = ServerWebURL.pathSegment(item.id) else { return "" }
        let destination = item.isSeries ? "/series/\(id)" : "/item/\(id)"
        let artwork = item.artworkAvailable ? "<img src=\"/api/v1/images/\(id)/poster\" alt=\"\" loading=\"lazy\" decoding=\"async\">" : "<span aria-hidden=\"true\">\(escape(String(item.type.prefix(1)).uppercased()))</span>"
        return "<li class=\"queue-item\(current ? " current" : "")\" data-item-id=\"\(escape(item.id))\" data-index=\"\(index)\"><span class=\"position\" aria-label=\"第 \(index + 1) 项\">\(index + 1)</span><a class=\"queue-link\" href=\"\(destination)\"><span class=\"queue-art\">\(artwork)<span class=\"mlink\">Mlink</span></span><span class=\"queue-copy\"><strong>\(escape(item.title))</strong><small>\(escape(item.type))\(item.year.map { " · \($0)" } ?? "")\(current ? " · 正在播放" : "")</small></span></a><span class=\"queue-actions\"><button class=\"move-up secondary\" type=\"button\" aria-label=\"上移 \(escape(item.title))\"\(index == 0 ? " disabled" : "")>↑</button><button class=\"move-down secondary\" type=\"button\" aria-label=\"下移 \(escape(item.title))\"\(index == 99 ? " disabled" : "")>↓</button><button class=\"remove-item secondary\" type=\"button\" aria-label=\"移除 \(escape(item.title))\">移除</button></span></li>"
    }

    static let style = """
    :root{--ink:#172033;--muted:#607086;--line:#dce7f2;--canvas:#f4f8fc;--surface:rgba(255,255,255,.9);--primary:#236fb5;--strong:#174d82;--danger:#b42318;--focus:#1570ef}*{box-sizing:border-box}html{min-width:320px}body{margin:0;overflow-x:hidden;color:var(--ink);background:var(--canvas);font:16px/1.55 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}a,button,select{touch-action:manipulation}:focus-visible{outline:3px solid var(--focus);outline-offset:3px}.skip{position:fixed;z-index:1000;top:8px;left:8px;padding:10px 14px;border-radius:10px;color:#fff;background:var(--strong);transform:translateY(-160%)}.skip:focus{transform:none}main{width:100%;max-width:1120px;min-width:0;padding:clamp(22px,4vw,48px)}h1{margin:0;font-size:clamp(36px,6vw,68px);line-height:1.05;letter-spacing:-.045em;overflow-wrap:anywhere}.eyebrow{margin:0 0 6px;color:var(--primary);font-size:13px;font-weight:800;letter-spacing:.08em;text-transform:uppercase}.heading>p{max-width:66ch;margin:12px 0;color:var(--muted)}.queue-toolbar{display:flex;flex-wrap:wrap;gap:16px;align-items:center;justify-content:space-between;margin-top:28px;padding:16px;border:1px solid var(--line);border-radius:18px;background:var(--surface);box-shadow:0 10px 30px #20385b0c}.queue-toolbar>div:first-child{display:grid;gap:3px}.queue-toolbar strong{font-size:18px}.queue-toolbar span{color:var(--muted);font-size:13px}.toolbar-actions{display:flex;flex-wrap:wrap;gap:9px;align-items:center}.select-control{display:flex;gap:8px;align-items:center;color:var(--muted);font-size:13px;font-weight:700}.select-control select{min-height:44px;padding:8px 10px;border:1px solid #bdcadb;border-radius:10px;color:var(--ink);background:#fff;font:inherit}.toolbar-actions button,.queue-actions button{min-height:44px;padding:8px 13px;border:1px solid var(--primary);border-radius:10px;color:#fff;background:var(--primary);font:inherit;font-weight:750;cursor:pointer}.toolbar-actions button.secondary,.queue-actions button.secondary{border-color:#a9bfd5;color:#23476a;background:#fff}.toolbar-actions button.danger{border-color:#d7837c;color:#9f2018;background:#fff7f6}.toolbar-actions button:hover,.queue-actions button:hover{background:#174d82;color:#fff}.toolbar-actions button.secondary:hover,.queue-actions button.secondary:hover{background:#eaf4ff;color:#174d82}.toolbar-actions button:disabled,.queue-actions button:disabled{opacity:.45;cursor:not-allowed}.queue-list{display:grid;gap:10px;margin:22px 0 0;padding:0;list-style:none}.queue-item{display:grid;grid-template-columns:36px minmax(0,1fr) auto;gap:12px;align-items:center;min-width:0;padding:10px;border:1px solid var(--line);border-radius:16px;background:var(--surface);box-shadow:0 8px 24px #2345670a;transition:border-color .18s ease,transform .18s ease}.queue-item.current{border-color:#7eb5e4;box-shadow:0 10px 28px #236fb522}.position{color:var(--muted);font-variant-numeric:tabular-nums;text-align:center}.queue-link{display:flex;gap:12px;align-items:center;min-width:0;color:inherit;text-decoration:none}.queue-art{position:relative;display:grid;flex:none;width:54px;height:76px;place-items:center;overflow:hidden;border-radius:9px;color:#fff;background:linear-gradient(145deg,#174d82,#4aa2df);font-weight:800}.queue-art img{width:100%;height:100%;object-fit:cover}.mlink{position:absolute;top:5px;left:5px;padding:2px 4px;border-radius:5px;color:#fff;background:#123b68e8;font-size:8px;font-weight:800}.queue-copy{min-width:0}.queue-copy strong{display:block;overflow-wrap:anywhere}.queue-copy small{display:block;margin-top:4px;color:var(--muted);overflow-wrap:anywhere}.queue-actions{display:flex;gap:6px;align-items:center}.queue-actions .remove-item{padding-inline:10px}.empty{margin-top:22px;padding:20px;border:1px dashed #b7cbe0;border-radius:14px;color:var(--muted);background:#fff}.empty a{color:var(--strong);font-weight:750}@media(max-width:720px){main{padding:24px 18px 40px}.queue-toolbar{align-items:stretch}.toolbar-actions{display:grid;grid-template-columns:1fr 1fr}.select-control{grid-column:1/-1;justify-content:space-between}.select-control select{flex:1}.toolbar-actions button{width:100%}.queue-item{grid-template-columns:28px minmax(0,1fr);gap:8px}.queue-actions{grid-column:2;justify-content:flex-end}.queue-actions button{flex:1}.queue-link{align-items:flex-start}}@media(max-width:430px){.toolbar-actions{grid-template-columns:1fr}.select-control{grid-column:auto}.queue-item{padding:8px}.queue-actions{gap:5px}.queue-actions button{padding-inline:8px}}@media(prefers-reduced-motion:reduce){*,*::before,*::after{transition-duration:.01ms!important}}
    """

    static let script = #"""
    (() => { 'use strict';
      const list = document.getElementById('queue-list'); const empty = document.getElementById('queue-empty'); const count = document.getElementById('queue-count'); const status = document.getElementById('queue-status'); const repeat = document.getElementById('repeat-mode'); const shuffle = document.getElementById('shuffle-toggle'); const clear = document.getElementById('clear-queue'); const csrf = document.querySelector('meta[name="medialib-csrf-token"]')?.content || ''; let state = null; let busy = false;
      const text = value => String(value ?? '').slice(0, 512); const button = (label, action, disabled) => { const node = document.createElement('button'); node.type = 'button'; node.className = 'secondary'; node.textContent = label; node.dataset.action = action; node.disabled = disabled === true; return node; };
      const fetchQueue = async signal => { const response = await fetch('/api/v1/queue', { credentials: 'same-origin', headers: { Accept: 'application/json' }, signal }); if (response.status === 401) { window.location.assign('/login'); return null; } if (!response.ok) throw new Error(); return response.json(); };
      const mutate = async payload => { if (busy) return; busy = true; status.textContent = '正在同步队列…'; const controller = new AbortController(); const timer = window.setTimeout(() => controller.abort(), 10000); try { const response = await fetch('/api/v1/queue', { method: 'POST', credentials: 'same-origin', headers: { Accept: 'application/json', 'Content-Type': 'application/json', 'X-MediaLIB-CSRF': csrf }, body: JSON.stringify(payload), signal: controller.signal }); if (response.status === 401) { window.location.assign('/login'); return; } if (!response.ok) throw new Error(); state = await response.json(); render(); } catch { status.textContent = '队列同步失败，请重试。'; } finally { window.clearTimeout(timer); busy = false; } };
      const render = () => { if (!state || !Array.isArray(state.items)) return; list.replaceChildren(); state.items.forEach((item, index) => { const row = document.createElement('li'); row.className = 'queue-item' + (index === Number(state.currentPosition) ? ' current' : ''); row.dataset.itemId = text(item.id); row.dataset.index = String(index); const position = document.createElement('span'); position.className = 'position'; position.textContent = String(index + 1); position.setAttribute('aria-label', `第 ${index + 1} 项`); const link = document.createElement('a'); link.className = 'queue-link'; link.href = `${item.isSeries === true ? '/series/' : '/item/'}${encodeURIComponent(text(item.id))}`; link.setAttribute('aria-label', `查看 ${text(item.title)}`); const art = document.createElement('span'); art.className = 'queue-art'; if (item.artworkAvailable === true) { const image = document.createElement('img'); image.alt = ''; image.loading = 'lazy'; image.decoding = 'async'; image.src = `/api/v1/images/${encodeURIComponent(text(item.id))}/poster`; art.append(image); } else art.textContent = text(item.type).slice(0, 1).toUpperCase(); const mark = document.createElement('span'); mark.className = 'mlink'; mark.textContent = 'Mlink'; art.append(mark); const copy = document.createElement('span'); copy.className = 'queue-copy'; const title = document.createElement('strong'); title.textContent = text(item.title) || '未命名媒体'; const meta = document.createElement('small'); meta.textContent = `${text(item.type)}${Number.isInteger(item.year) ? ` · ${item.year}` : ''}${index === Number(state.currentPosition) ? ' · 正在播放' : ''}`; copy.append(title, meta); link.append(art, copy); const actions = document.createElement('span'); actions.className = 'queue-actions'; actions.append(button('↑', 'up', index === 0), button('↓', 'down', index === state.items.length - 1), button('移除', 'remove')); row.append(position, link, actions); list.append(row); }); const total = state.items.length; count.textContent = `${total} 项`; status.textContent = total ? '已同步' : '队列为空，请从资料库加入媒体。'; empty.hidden = total > 0; clear.disabled = total === 0; repeat.value = ['sequential', 'repeatOne', 'repeatAll'].includes(state.repeatMode) ? state.repeatMode : 'sequential'; shuffle.textContent = state.shuffleEnabled === true ? '关闭随机' : '开启随机'; shuffle.setAttribute('aria-pressed', state.shuffleEnabled === true ? 'true' : 'false'); };
      list.addEventListener('click', event => { const target = event.target.closest('button[data-action]'); if (!target) return; const row = target.closest('.queue-item'); const index = Number(row?.dataset.index); if (!Number.isInteger(index) || !state) return; if (target.dataset.action === 'remove') mutate({ action: 'remove', mediaID: row.dataset.itemId }); else if (target.dataset.action === 'up' && index > 0) mutate({ action: 'move', fromIndex: index, toIndex: index - 1 }); else if (target.dataset.action === 'down' && index < state.items.length - 1) mutate({ action: 'move', fromIndex: index, toIndex: index + 1 }); });
      repeat.addEventListener('change', () => mutate({ action: 'settings', repeatMode: repeat.value })); shuffle.addEventListener('click', () => mutate({ action: 'settings', shuffleEnabled: !(state?.shuffleEnabled === true) })); clear.addEventListener('click', () => { if (state?.items?.length && window.confirm('清空当前播放队列？')) mutate({ action: 'clear' }); });
      (async () => { const controller = new AbortController(); const timer = window.setTimeout(() => controller.abort(), 10000); try { state = await fetchQueue(controller.signal); render(); } catch { status.textContent = '队列载入失败，请刷新重试。'; } finally { window.clearTimeout(timer); } })();
    })();
    """#

    private static func escape(_ value: String) -> String { value.replacingOccurrences(of: "&", with: "&amp;").replacingOccurrences(of: "<", with: "&lt;").replacingOccurrences(of: ">", with: "&gt;").replacingOccurrences(of: "\"", with: "&quot;").replacingOccurrences(of: "'", with: "&#39;") }
}
